SELECT TOP 2 (CAST(`Free Meal Count (K-12)` AS REAL) / `Enrollment (K-12)`) AS EligibleFreeRate
FROM frpm
ORDER BY `Enrollment (K-12)` DESC;

SELECT COUNT(CDSCode) / 12 AS MonthlyAverage
FROM schools
WHERE County = 'Alameda' AND DOC = 52 AND STRFTIME('%Y', OpenDate) = '1980';

SELECT CAST(SUM(CASE WHEN T1.County = 'Colusa' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN T1.County = 'Humboldt' THEN 1 ELSE 0 END) AS Ratio
FROM schools AS T1
WHERE T1.State = 'CA';

SELECT COUNT(*) 
FROM schools 
WHERE MailState = 'CA' AND City = 'San Joaquin' AND StatusType = 'Active';

SELECT COUNT(*) 
FROM schools 
WHERE City = 'Hickman' AND Charter = 1 AND DOC = 52;

SELECT COUNT(*) 
FROM schools 
WHERE CharterNum = '00D4' AND MailCity = 'Hickman';

SELECT COUNT(*) 
FROM schools 
WHERE City = 'San Francisco' AND StatusType = 'Closed' AND ClosedDate LIKE '1989%';

SELECT T1.AdmLName1, T1.District, T1.County, T1.School 
FROM schools AS T1 
WHERE T1.CharterNum = '40';

SELECT COUNT(district_id) 
FROM district 
WHERE A11 > 6000 AND A11 < 10000;

SELECT COUNT(*) 
FROM connected 
WHERE (atom_id = 'TR009_12' OR atom_id2 = 'TR009_12') AND molecule_id = 'TR009';

SELECT COUNT(*) 
FROM molecule 
WHERE molecule_id BETWEEN 'TR000' AND 'TR030' AND label = '+';

SELECT CAST(SUM(CASE WHEN T2.bond_type = '#' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(T1.molecule_id) AS percentage
FROM molecule AS T1
JOIN bond AS T2 ON T1.molecule_id = T2.molecule_id;

SELECT CAST(SUM(CASE WHEN bond_type = ' = ' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(bond_id) AS percent
FROM bond
WHERE molecule_id = 'TR047';

SELECT CAST(SUM(CASE WHEN T1.label = '+' AND T2.element = 'h' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(T1.molecule_id) AS percentage
FROM molecule AS T1
JOIN atom AS T2 ON T1.molecule_id = T2.molecule_id;

SELECT COUNT(DISTINCT molecule_id) 
FROM bond 
WHERE molecule_id BETWEEN 'TR004' AND 'TR010' AND bond_type = '-';

SELECT MAX(AnswerCount) AS MostAnswers
FROM posts
WHERE OwnerDisplayName = 'csgillespie';

SELECT SUM(CASE WHEN T1.eye_colour_id = 7 THEN 1 ELSE 0 END) - SUM(CASE WHEN T1.eye_colour_id = 1 THEN 1 ELSE 0 END) AS difference
FROM superhero AS T1
WHERE T1.weight_kg = 0 OR T1.weight_kg IS NULL;

SELECT CAST(SUM(CASE WHEN type = 'Community Service' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(event_id) AS percentage
FROM event
WHERE event_date BETWEEN '2019-01-01' AND '2019-12-31';

SELECT MAX(cost) AS most_money
FROM expense
WHERE expense_description = 'Water, chips, cookies';
